@namespace sv_6fdb221ce17b4a36a5abcabaeefa79df.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var state = step < CurrentStep ? "completed"
                      : step == CurrentStep ? "active"
                      : "upcoming";
            <div class="text-center flex-fill step-item @state"
                 role="button"
                 @onclick="() => OnStepClick(step)"
                 style="cursor: @(step < CurrentStep ? "pointer" : "default")">
                <div class="d-flex justify-content-center mb-1">
                    <span class="rounded-circle d-inline-flex align-items-center justify-content-center @GetBadgeClass(state)"
                          style="width: 2rem; height: 2rem; font-size: 0.85rem;">
                        @if (state == "completed")
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @(step + 1)
                        }
                    </span>
                </div>
                <small class="@GetLabelClass(state)">@StepNames[step]</small>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetBadgeClass(string state) => state switch
    {
        "completed" => "bg-success text-white",
        "active"    => "bg-primary text-white",
        _           => "bg-secondary text-white opacity-50"
