@namespace sv_6fdb221ce17b4a36a5abcabaeefa79df.Components.Pages.Apply
@using sv_6fdb221ce17b4a36a5abcabaeefa79df.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(Error))
{
    <div class="alert alert-danger">@Error</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var idx = i;
    var entry = Entries[idx];
    <WorkEntryForm Index="@(idx + 1)"
                   Company="@entry.Company"
                   Title="@entry.Title"
                   StartDate="@entry.StartDate"
                   EndDate="@entry.EndDate"
                   IsCurrent="@entry.IsCurrent"
                   Description="@entry.Description"
                   CanRemove="@(Entries.Count > 1)"
                   OnChanged="data => UpdateEntry(idx, data)"
                   OnRemove="() => RemoveEntry(idx)" />
}

<button type="button" class="btn btn-outline-primary btn-sm mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<EntryModel>? InitialEntries { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? Error;

    public class EntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private List<EntryModel> Entries = new();

    protected override void OnInitialized()
    {
        if (InitialEntries is { Count: > 0 })
        {
            Entries = InitialEntries.Select(e => new EntryModel
            {
                Company = e.Company, Title = e.Title, StartDate = e.StartDate,
                EndDate = e.EndDate, IsCurrent = e.IsCurrent, Description = e.Description
            }).ToList();
        }
        else
        {
            Entries.Add(new EntryModel());
        }
    }

    private void AddEntry() => Entries.Add(new EntryModel());

    private void RemoveEntry(int index) { if (Entries.Count > 1) Entries.RemoveAt(index); }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        var e = Entries[index];
        e.Company = data.Company;
        e.Title = data.Title;
        e.StartDate = data.StartDate;
        e.EndDate = data.EndDate;
        e.IsCurrent = data.IsCurrent;
        e.Description = data.Description;
    }

    private async Task HandleNext()
    {
        Error = null;
        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            Error = "Each position requires at least a company name and job title.";
            return;
        }

        var result = Entries.Select(e => new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate,
            e.IsCurrent ? null : e.EndDate, e.Description.Trim())).ToList();
        await OnNext.InvokeAsync(result);
    }
}

