    var r = Refs[idx];
    <ReferenceForm Index="@(idx + 1)"
                   Name="@r.Name"
                   Relationship="@r.Relationship"
                   Email="@r.Email"
                   Phone="@r.Phone"
                   CanRemove="@(Refs.Count > 1)"
                   OnChanged="data => UpdateRef(idx, data)"
                   OnRemove="() => RemoveRef(idx)" />
}

@if (Refs.Count < 3)
{
    <button type="button" class="btn btn-outline-primary btn-sm mb-3" @onclick="AddRef">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<RefModel>? InitialRefs { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? Error;

    public class RefModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }

    private List<RefModel> Refs = new();

    protected override void OnInitialized()
    {
        if (InitialRefs is { Count: > 0 })
        {
            Refs = InitialRefs.Select(r => new RefModel
            {
                Name = r.Name, Relationship = r.Relationship, Email = r.Email, Phone = r.Phone
            }).ToList();
        }
        else
        {
            Refs.Add(new RefModel());
        }
    }

    private void AddRef() { if (Refs.Count < 3) Refs.Add(new RefModel()); }

    private void RemoveRef(int index) { if (Refs.Count > 1) Refs.RemoveAt(index); }

    private void UpdateRef(int index, ReferenceForm.ReferenceData data)
    {
        var r = Refs[index];
        r.Name = data.Name;
        r.Relationship = data.Relationship;
        r.Email = data.Email;
        r.Phone = data.Phone;
    }

    private async Task HandleNext()
    {
        Error = null;
        if (Refs.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            Error = "Each reference requires at least a name and email.";
            return;
        }

        var result = Refs.Select(r => new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())).ToList();
        await OnNext.InvokeAsync(result);
    }
}

