@page "/apply"
@using sv_6fdb221ce17b4a36a5abcabaeefa79df.Components.Pages.Apply
@using sv_6fdb221ce17b4a36a5abcabaeefa79df.Models
@using sv_6fdb221ce17b4a36a5abcabaeefa79df.Services
@inject IApplicationService AppService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" StepNames="@_stepNames" OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  ValidateEmail="AppService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep InitialEntries="@_workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep InitialRefs="@_refEntries" OnNext="HandleRefsNext" OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter" OnNext="HandleCoverNext" OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@BuildPersonalInfo()"
                            WorkEntries="@_workResults"
                            References="@_refResults"
                            CoverLetter="@_coverLetter"
                            OnEditStep="GoToStep"
                            OnBack="GoBack"
                            SubmitApplication="SubmitAsync" />
                break;
        }
    </div>
</div>

@code {
    private static readonly IReadOnlyList<string> _stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int _currentStep;

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkHistoryStep.EntryModel>? _workEntries;
    private List<WorkEntry> _workResults = new();

    // Step 3 state
    private List<ReferencesStep.RefModel>? _refEntries;
    private List<Reference> _refResults = new();

    // Step 4 state
    private string _coverLetter = string.Empty;

    private void GoToStep(int step) => _currentStep = step;
    private void GoBack() => _currentStep = Math.Max(0, _currentStep - 1);

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        _workResults = entries;
        _workEntries = entries.Select(e => new WorkHistoryStep.EntryModel
        {
            Company = e.Company, Title = e.Title, StartDate = e.StartDate,
            EndDate = e.EndDate, IsCurrent = !e.EndDate.HasValue, Description = e.Description
        }).ToList();
        _currentStep = 2;
    }

    private void HandleRefsNext(List<Reference> refs)
    {
        _refResults = refs;
        _refEntries = refs.Select(r => new ReferencesStep.RefModel
        {
            Name = r.Name, Relationship = r.Relationship, Email = r.Email, Phone = r.Phone
        }).ToList();
        _currentStep = 3;
    }

    private void HandleCoverNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private PersonalInfo BuildPersonalInfo() => new(_fullName, _email, _phone, _address);

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            BuildPersonalInfo(),
            new WorkHistory(_workResults),
            _refResults,
            _coverLetter
        );
        return await AppService.SubmitApplicationAsync(application);
    }
}

