@namespace sv_6fdb221ce17b4a36a5abcabaeefa79df.Components.Pages.ApplySteps

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>
        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input class="form-control" value="@Company" @onchange="OnCompanyChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input class="form-control" value="@Title" @onchange="OnTitleChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@FormatDate(StartDate)"
                       @onchange="OnStartDateChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@FormatNullableDate(EndDate)"
                       disabled="@IsCurrent"
                       @onchange="OnEndDateChanged" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@CheckboxId" checked="@IsCurrent"
                           @onchange="OnIsCurrentChanged" />
                    <label class="form-check-label" for="@CheckboxId">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="OnDescriptionChanged"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public int Index { get; set; }

    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);

    private string CheckboxId => $"current-{Index}";
    private static string FormatDate(DateTime d) => d.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? d) => d?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void OnCompanyChanged(ChangeEventArgs e) { Company = (string?)e.Value ?? string.Empty; NotifyChanged(); }
    private void OnTitleChanged(ChangeEventArgs e) { Title = (string?)e.Value ?? string.Empty; NotifyChanged(); }
    private void OnDescriptionChanged(ChangeEventArgs e) { Description = (string?)e.Value ?? string.Empty; NotifyChanged(); }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var d)) StartDate = d;
        NotifyChanged();
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnIsCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }
}

