<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>
        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input class="form-control" value="@Name" @onchange="OnNameChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input class="form-control" value="@Relationship" @onchange="OnRelationshipChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" value="@Email" @onchange="OnEmailChanged" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" value="@Phone" @onchange="OnPhoneChanged" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public int Index { get; set; }

    [Parameter] public string Name { get; set; } = string.Empty;
    [Parameter] public string Relationship { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);

    private void OnNameChanged(ChangeEventArgs e) { Name = (string?)e.Value ?? string.Empty; NotifyChanged(); }
    private void OnRelationshipChanged(ChangeEventArgs e) { Relationship = (string?)e.Value ?? string.Empty; NotifyChanged(); }
    private void OnEmailChanged(ChangeEventArgs e) { Email = (string?)e.Value ?? string.Empty; NotifyChanged(); }
    private void OnPhoneChanged(ChangeEventArgs e) { Phone = (string?)e.Value ?? string.Empty; NotifyChanged(); }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }
}

